def count_nums(arr):
    def digit_sum(n):
        n = abs(n)
        total = 0
        while n > 0:
            total += n % 10
            n = n // 10
        return total

    count = 0
    for num in arr:
        if digit_sum(num) > 0:
            count += 1
    return count
